css:
.vo2064-container{--vo-ink:#141d2b;--vo-deep:#1d3f57;--vo-accent:#0f6b5c;--vo-warn:#9a4a17;--vo-bad:#a33017;--vo-rule:#d3dce3;--vo-muted:#4f5d6a;--vo-tint:#eaf0f3;--vo-card:#ffffff;font-family:"Segoe UI",system-ui,-apple-system,sans-serif;color:var(--vo-ink);background:#f6f8f9;max-width:1120px;margin:0 auto;padding:18px 18px 32px;border-radius:14px;line-height:1.45}
.vo2064-container *{box-sizing:border-box}
.vo2064-header{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;border-bottom:3px solid var(--vo-deep);padding-bottom:10px;margin-bottom:12px}
.vo2064-header h1{margin:0;font-size:1.85rem;letter-spacing:-.02em;color:var(--vo-ink)}
.vo2064-sub{margin:2px 0 0;color:var(--vo-muted);font-size:.9rem}
.vo2064-clock{text-align:right;font-size:.82rem;color:var(--vo-muted)}
.vo2064-clock strong{display:block;font-size:1.65rem;color:var(--vo-deep);line-height:1.1}
.vo2064-small{font-size:.78rem}
.vo2064-steps{list-style:none;display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:0 0 16px;padding:0}
.vo2064-steps li{background:var(--vo-tint);border-radius:8px;padding:6px 9px;font-size:.74rem;color:var(--vo-muted);border-top:3px solid var(--vo-rule)}
.vo2064-steps li b{display:block;font-size:.9rem;color:var(--vo-ink)}
.vo2064-steps li.vo2064-done{border-top-color:var(--vo-accent)}
.vo2064-steps li.vo2064-now{background:var(--vo-deep);border-top-color:var(--vo-deep);color:#e4edf2}
.vo2064-steps li.vo2064-now b{color:#fff}
.vo2064-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:10px}
.vo2064-kpi{background:var(--vo-card);border:1px solid var(--vo-rule);border-radius:10px;padding:10px 12px}
.vo2064-kpi span{font-size:.76rem;color:var(--vo-muted)}
.vo2064-kpi>span{display:block}
.vo2064-kpi strong{display:block;font-size:1.45rem;margin:2px 0 1px;color:var(--vo-deep)}
.vo2064-kpi em{font-style:normal;font-size:.72rem;color:var(--vo-muted)}
.vo2064-kpi i{font-style:normal;font-weight:700;margin-left:4px}
.vo2064-up{color:var(--vo-accent)}
.vo2064-down{color:var(--vo-bad)}
.vo2064-gauges{display:grid;grid-template-columns:repeat(3,1fr);gap:8px 12px;margin-bottom:16px}
.vo2064-gauge{display:flex;justify-content:space-between;align-items:baseline;gap:10px;background:var(--vo-tint);border-radius:8px;padding:7px 11px;font-size:.78rem;color:var(--vo-muted)}
.vo2064-gauge b{color:var(--vo-ink);font-size:.95rem;white-space:nowrap}
.vo2064-gauge b.vo2064-hot{color:var(--vo-bad)}
.vo2064-brief{background:var(--vo-card);border-left:4px solid var(--vo-accent);padding:12px 15px;border-radius:0 8px 8px 0;margin-bottom:10px;font-size:.94rem;line-height:1.55;box-shadow:0 1px 4px rgba(20,29,43,.07)}
.vo2064-alerts:empty{display:none}
.vo2064-alerts{margin-bottom:14px;display:grid;gap:6px}
.vo2064-alert{background:#fff4e8;border:1px solid #e6c49f;color:#5c2d09;border-radius:8px;padding:8px 12px;font-size:.87rem}
.vo2064-alert.vo2064-good{background:#e8f4f0;border-color:#a9cfc5;color:#0b4a40}
.vo2064-alert.vo2064-crit{background:#fbe6e2;border-color:#e2a99c;color:#7a2210}
.vo2064-portfolio,.vo2064-levers,.vo2064-panel,.vo2064-report,.vo2064-final,.vo2064-charts,.vo2064-history{border:1px solid var(--vo-rule);border-radius:12px;padding:16px 18px;margin-bottom:16px;background:var(--vo-card)}
.vo2064-panel,.vo2064-report,.vo2064-final{display:none}
.vo2064-panel.vo2064-on,.vo2064-report.vo2064-on,.vo2064-final.vo2064-on{display:block}
.vo2064-panel{border-left:4px solid var(--vo-warn)}
.vo2064-container h2{margin:0 0 6px;font-size:1.1rem;color:var(--vo-deep)}
.vo2064-container h3{margin:0 0 8px;font-size:.86rem;color:var(--vo-ink);font-weight:600}
.vo2064-help{margin:0 0 14px;font-size:.87rem;color:var(--vo-muted);line-height:1.5}
.vo2064-note{margin:8px 0 0;font-size:.8rem;color:var(--vo-muted);line-height:1.45}
.vo2064-split{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:18px;align-items:start}
.vo2064-sectors{display:grid;gap:12px}
.vo2064-sector{display:grid;grid-template-columns:1fr 54px;gap:3px 10px;align-items:center;padding-bottom:10px;border-bottom:1px dashed var(--vo-rule)}
.vo2064-sector:last-child{border-bottom:0;padding-bottom:0}
.vo2064-sector label{grid-column:1/-1;display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-size:.87rem;font-weight:600;margin:0}
.vo2064-sector small,.vo2064-field small{font-weight:400;font-size:.75rem;color:var(--vo-muted);text-align:right}
.vo2064-sector small.vo2064-ok{color:var(--vo-accent);font-weight:600}
.vo2064-sector input{width:100%}
.vo2064-sector output,.vo2064-field output{font-weight:700;color:var(--vo-deep);text-align:right;font-size:.92rem}
.vo2064-facts{grid-column:1/-1;margin:0;font-size:.75rem;color:var(--vo-muted)}
.vo2064-sector-legacy label span{color:var(--vo-warn)}
.vo2064-budget{margin:0 0 4px;padding:10px 13px;border-radius:8px;background:var(--vo-tint);font-size:.9rem;font-weight:600;color:var(--vo-ink)}
.vo2064-budget.vo2064-over{background:#fbe6e2;color:#7a2210}
.vo2064-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px}
.vo2064-programs{display:grid;gap:12px;align-content:start}
.vo2064-field{display:grid;grid-template-columns:1fr 54px;gap:4px 10px;align-items:center;font-size:.86rem}
.vo2064-field label{grid-column:1/-1;display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-weight:600;margin:0}
.vo2064-field select{grid-column:1/-1;padding:8px 9px;border:1px solid #8796a3;border-radius:7px;font-size:.9rem;background:#fff;color:var(--vo-ink);width:100%}
.vo2064-field input[type=range]{width:100%}
.vo2064-profile{grid-column:1/-1;display:grid;gap:5px;margin-top:8px}
.vo2064-bar{display:grid;grid-template-columns:150px 1fr;gap:8px;align-items:center;font-size:.76rem;color:var(--vo-muted)}
.vo2064-bar div{height:8px;border-radius:4px;background:var(--vo-tint);overflow:hidden}
.vo2064-bar div span{display:block;height:100%;background:var(--vo-deep);border-radius:4px}
.vo2064-bar.vo2064-cost div span{background:var(--vo-warn)}
.vo2064-actions{text-align:right;margin:14px 0 18px}
.vo2064-btn{background:var(--vo-deep);color:#fff;border:0;border-radius:9px;padding:12px 28px;font-size:1rem;font-weight:600;cursor:pointer}
.vo2064-btn:hover{background:var(--vo-accent)}
.vo2064-btn:disabled{opacity:.45;cursor:not-allowed}
.vo2064-container :focus-visible{outline:3px solid #c46a1b;outline-offset:2px;border-radius:4px}
.vo2064-chart-pair,.vo2064-chart-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.vo2064-chart-box{border:1px solid var(--vo-rule);border-radius:10px;padding:12px;background:#fff;min-width:0}
.vo2064-chart-side{position:sticky;top:12px}
.vo2064-verdict{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;margin:4px 0 12px}
.vo2064-verdict strong{font-size:1.35rem;color:var(--vo-deep)}
.vo2064-verdict span{font-size:1.05rem;font-weight:700;color:var(--vo-ink)}
.vo2064-parts{display:grid;gap:6px;margin-bottom:12px}
.vo2064-parts .vo2064-bar{grid-template-columns:230px 1fr 70px;font-size:.82rem;color:var(--vo-ink)}
.vo2064-parts .vo2064-bar div{height:11px}
.vo2064-parts .vo2064-bar b{text-align:right;font-weight:600}
.vo2064-insights{margin:0;padding-left:18px;font-size:.9rem;line-height:1.55}
.vo2064-insights li{margin-bottom:5px}
.vo2064-tablewrap{overflow-x:auto}
.vo2064-history table{width:100%;border-collapse:collapse;font-size:.86rem}
.vo2064-history th,.vo2064-history td{padding:7px 9px;border-bottom:1px solid var(--vo-rule);text-align:right;white-space:nowrap;color:var(--vo-ink)}
.vo2064-history th:first-child,.vo2064-history td:first-child{text-align:left}
.vo2064-history th{color:var(--vo-muted);font-weight:600}
.vo2064-debrief{font-size:.95rem;line-height:1.55}
.vo2064-debrief h4{margin:0 0 4px;font-size:1.25rem;color:#1d3f57}
.vo2064-debrief p{margin:0 0 10px}
.vo2064-debrief ul{margin:0;padding-left:18px}
.vo2064-debrief li{margin-bottom:5px}
@media (max-width:860px){.vo2064-split,.vo2064-grid,.vo2064-chart-pair,.vo2064-chart-grid{grid-template-columns:minmax(0,1fr)}.vo2064-chart-side{position:static}.vo2064-gauges{grid-template-columns:repeat(2,1fr)}}
@media (max-width:720px){.vo2064-kpis{grid-template-columns:repeat(2,1fr)}.vo2064-header{flex-direction:column;align-items:flex-start}.vo2064-clock{text-align:left}.vo2064-steps li span{display:none}.vo2064-gauges{grid-template-columns:minmax(0,1fr)}.vo2064-parts .vo2064-bar{grid-template-columns:130px 1fr 60px}.vo2064-bar{grid-template-columns:110px 1fr}}
@media (prefers-reduced-motion:reduce){.vo2064-container *{transition:none!important;animation:none!important}}

