                fund: 14,
                taxStream: 0,
                embed: 0.1,
                anchorBias: 0,
                dispFactor: 1,
                talentCap: 3,
                concentration: 58,
                gdp: 100,
                hhi: null,
                exposure: 0,
                promise: null,
                lobby: null,
                election: null,
                outcome: null,
                pact: false,
                pactAlloc: null,
                agencyAlive: true,
                shock: null,
                finalRec: null
            };
        }

        _clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
        _r1(v) { return Math.round(v * 10) / 10; }
        _r2(v) { return Math.round(v * 100) / 100; }

        // Share of a vintage that is already producing, given its age and the
        // sector lag shifted by the instrument that delivered the money.
        _maturity(age, lag) { return this._clamp((age - lag + 2) / 3, 0, 1); }

        _stocks(ds) {
            const st = [0, 0, 0, 0, 0];
            ds.vint.forEach(v => v.k.forEach((k, i) => { st[i] += k; }));
            return st;
        }

        // How much of each new sector would walk away if its anchor firms left:
        // footloose money everywhere, plus a concentration premium on the sector
        // that carries the portfolio.
        _risk(ds) {
            const tot = ds.out.reduce((a, b) => a + b, 0);
            if (tot < 0.05) return null;
            let top = 0;
            ds.out.forEach((o, i) => { if (o > ds.out[top]) top = i; });
            const share = ds.out[top] / tot;
            const sev = this.SECTORS.map((s, i) => {
                let money = 0, anchored = 0;
                ds.vint.forEach(v => { money += v.k[i]; anchored += v.k[i] * v.anchor; });
                if (money <= 0) return 0;
                const foot = this._clamp(0.5 * s.foot + anchored / money + ds.anchorBias, 0.05, 1);
                const conc = i === top ? this._clamp((share - 0.3) / 0.45, 0, 1) : 0;
                return (0.35 + 0.4 * conc) * foot * (1 - 0.7 * ds.embed);
            });
            let loss = 0;
            ds.out.forEach((o, i) => { loss += o * sev[i]; });
            return { index: top, share: share, severity: sev, total: tot, exposure: loss / tot };
        }

        _applyShock(ds, d, note) {
            const risk = this._risk(ds);
            if (!risk || risk.exposure < 0.01) { ds.shock = { sector: risk ? risk.index : -1, loss: 0, response: 'none', lost: 0 }; return; }
            const resp = d.voShock || 'letgo';
            const damp = resp === 'retain' ? 0.5 : (resp === 'replace' ? 0.75 : 1);
            let lost = 0;
            ds.vint.forEach(v => { v.k = v.k.map((k, i) => { const cut = k * risk.severity[i] * damp; lost += cut; return k - cut; }); });
            if (resp === 'retain') { note.fund.deals = (note.fund.deals || 0) - 0.8; ds.anchorBias += 0.15; note.sup.dilemma = 1; }
            if (resp === 'replace') { ds.anchorBias += 0.1; }
            if (resp === 'letgo') {
                // A quarter of what leaves stays behind as spin-offs and suppliers,
                // spread over the sectors that still have critical mass.
                const st = this._stocks(ds);
                const heirs = this.SECTORS.map((s, i) => (st[i] >= s.threshold ? st[i] : 0));
                const pool = heirs.reduce((a, b) => a + b, 0);
                if (pool > 0 && ds.vint.length) {
                    heirs.forEach((h, i) => { if (h > 0) ds.vint[0].k[i] += lost * 0.25 * h / pool; });
                }
                ds.embed = this._clamp(ds.embed + 0.06, 0, 0.9);
                note.sup.dilemma = -2;
            }
            ds.shock = { sector: risk.index, loss: this._r2(risk.exposure * damp), response: resp, lost: this._r1(lost) };
        }

        _step(ds, d, p) {
            const S = this.SECTORS;
            const instrKey = this.INSTRUMENT[d.voInstrument] ? d.voInstrument : 'grant';
            const I = this.INSTRUMENT[instrKey];
            const num = (k) => { const v = parseFloat(d[k]); return isNaN(v) ? 0 : v; };
            const alloc = S.map(s => num(s.id));
            const legacySpend = num('voLegacy');
            const talent = Math.min(num('voTalent'), ds.talentCap), local = num('voLocal'), housing = num('voHousing');
            const note = { sup: {}, fund: {}, events: [] };
            const prevLegacy = ds.legacy, prevFund = ds.fund, prevSupport = ds.support;

            // 1 · dilemmas that redirect this year's money
            let sectorMoney = alloc.slice();
            if (p === 1) ds.promise = d.voPromise || 'quiet';
            if (p === 2) {
                ds.lobby = d.voLobby || 'ignore';
                if (ds.lobby === 'codesign' && local < 2) ds.lobby = 'empty';
            }
            if (p === 3) ds.election = d.voElection || 'hold';
            if (p === 3 && ds.election === 'quick') sectorMoney = sectorMoney.map(v => v * 0.7);

            // 2 · the 2030 shock lands on whatever carries the portfolio
            if (p === 4) {
                this._applyShock(ds, d, note);
                if (ds.shock && ds.shock.response === 'replace' && ds.shock.sector >= 0) {
                    sectorMoney[ds.shock.sector] += this.REPLACE;
                }
            }

            // 3 · depreciation of what was already there, then the new vintage
            const keep = (ds.pact ? 0.85 : 1) * (1 - 0.5 * ds.embed);
            ds.vint.forEach(v => { v.k = v.k.map(k => k * (1 - v.dep * keep)); });
            const wait = (p === 3 && ds.election !== 'pact') ? 0.95 : ((p === 2 && ds.lobby === 'codesign') ? 0.9 : 1);
            ds.vint.push({
                p: p, instr: instrKey, dep: I.dep, shift: I.shift, anchor: I.anchor,
                k: sectorMoney.map(v => v * I.mult * wait)
            });
            const invested = sectorMoney.reduce((a, b) => a + b, 0);
            ds.embed = this._clamp(ds.embed + I.embed * invested + 0.03 * local, 0, 0.9);

            // 4 · critical mass and potential output
            ds.stock = this._stocks(ds).map(v => this._r2(v));
            let active = 0, below = 0;
            ds.pot = S.map((s, i) => {
                const on = ds.stock[i] >= s.threshold;
                if (on) active++; else if (alloc[i] > 0) below += alloc[i];
                let prod = 0;
                ds.vint.forEach(v => { prod += v.k[i] * this._maturity(p - v.p, s.lag + v.shift); });
                const kin = s.kin ? this._clamp(0.7 + 0.3 * (ds.legacy - 80) / 20, 0.7, 1) : 1;
                return prod * s.yield * kin * this.G * (on ? 1 : 0.15);
            });
            ds.embed = this._clamp(ds.embed + 0.004 * ds.stock[3], 0, 0.9);

            // 5 · people: specialists come from outside, general profiles from inside
            const talentIn = Math.round(talent * 110 * this._clamp(1 - 0.06 * Math.max(0, ds.housing - 4), 0.5, 1));
            ds.specPool += talentIn + 25 + Math.round(18 * ds.pot[3]);
            ds.genPool += ds.trainees + 40;
            ds.trainees = Math.round(local * 80 * (ds.lobby === 'codesign' ? 1.25 : 1));
            let needSpec = 0, needGen = 0;
            S.forEach((s, i) => { needSpec += ds.pot[i] * s.jpp * s.spec; needGen += ds.pot[i] * s.jpp * (1 - s.spec); });
            const fillSpec = needSpec > 0 ? Math.min(1, ds.specPool / needSpec) : 1;
            const spare = Math.max(0, ds.specPool - needSpec);
            const fillGen = needGen > 0 ? Math.min(1, (ds.genPool + spare) / needGen) : 1;
            ds.out = S.map((s, i) => this._r2(ds.pot[i] * Math.pow(fillSpec, s.spec) * Math.pow(fillGen, 1 - s.spec)));
            // idle people do not wait for ever
            ds.specPool = Math.round(Math.min(ds.specPool, needSpec) + Math.max(0, ds.specPool - needSpec) * 0.7);
            ds.genPool = Math.round(Math.min(ds.genPool, needGen) + Math.max(0, ds.genPool - needGen) * 0.7);
            let jobsNew = 0;
            S.forEach((s, i) => { jobsNew += ds.out[i] * s.jpp; });
            jobsNew = Math.round(jobsNew);
            const created = jobsNew - ds.jobsNew;
            ds.jobsNew = jobsNew;

            // 6 · the traditional sector erodes on its own and can only be slowed
            let defence = 3.4 * (1 - Math.exp(-legacySpend / 3.5));
            if (p === 2 && ds.lobby === 'compensate') defence += 0.5;
            ds.legacy = this._r1(this._clamp(ds.legacy - 3 + defence, 50, 100));
            const displaced = Math.round(Math.max(0, prevLegacy - ds.legacy) * 122 * ds.dispFactor);
            if (p === 2 && ds.lobby === 'codesign') ds.dispFactor = 0.7;
            const netJobs = created - displaced;
            ds.jobs += netJobs;

            // 7 · housing: talent adds more pressure than support can remove
            ds.housing = this._r1(this._clamp(ds.housing + 0.2 + talentIn / 100 * 0.7 - housing * 0.8, 0, 10));
            ds.talentCap = ds.housing >= 8 ? 1 : 3;

            // 8 · reserve fund, in months of current spending
            const newOut = ds.out.reduce((a, b) => a + b, 0);
            if (instrKey === 'fiscal') ds.taxStream = this._r2(ds.taxStream + 0.35);
            const used = alloc.reduce((a, b) => a + b, 0) + legacySpend +
                talent * this.COST.voTalent + local * this.COST.voLocal + housing * this.COST.voHousing +
                ((p === 2 && ds.lobby === 'compensate') ? this.COMPENSATION : 0) +
                ((p === 4 && ds.shock && ds.shock.response === 'replace' && ds.shock.sector >= 0) ? this.REPLACE : 0) +
                ((ds.pact && (p === 4 || p === 5)) ? this.PACT_TOLL : 0);
            const unspent = Math.max(0, ds.budget - used);
            note.fund.newRevenue = this._r2(0.10 * newOut);
            note.fund.legacyLoss = -this._r2(0.09 * (100 - ds.legacy));
            note.fund.taxBreaks = -ds.taxStream;
            if (instrKey === 'capture') note.fund.deals = (note.fund.deals || 0) - 0.4;
            if (p === 3 && ds.election === 'quick') note.fund.deals = (note.fund.deals || 0) - 0.6;
            if (unspent > 0.01) note.fund.unspent = this._r2(unspent * 0.03);
            let dFund = 0;
            Object.keys(note.fund).forEach(k => { dFund += note.fund[k]; });
            ds.fund = this._r1(Math.max(0, ds.fund + dFund));

            // 9 · public support
            const sup = note.sup;
            sup.fatigue = -1.5;
            sup.instrument = I.support;
            sup.jobs = this._r1(this._clamp(netJobs / 80, -4, 3));
            sup.housing = this._r1(this._clamp(-0.9 * (ds.housing - 3), -6, 1));
            sup.inclusion = this._r1(0.8 * local - 0.7 * Math.max(0, talent - local));
            const ask = (ds.lobby === 'compensate' && p > 2) ? 1 : 0;   // once paid, they come back for more
            sup.legacy = legacySpend >= 3 + ask ? 1 : (legacySpend >= 1.5 + ask ? 0 : -1.5);
            if (ds.stock[4] >= S[4].threshold) sup.visible = 0.5;
            if (ds.fund < 9) sup.fundAlarm = -2.5;
            if (ds.promise === 'promise') {
                if (p <= 2) sup.narrative = 3;
                if (p === 3) sup.narrative = ds.jobs >= 250 ? 3 : -8;
            }
            if (ds.promise === 'honest') {
                if (p === 1) sup.narrative = -2;
                else if (p <= 3) { if (sup.jobs < 0) sup.jobs = this._r1(sup.jobs / 2); if (p === 3) sup.narrative = 1; }
            }
            if (p === 2) sup.dilemma = ({ compensate: 3, codesign: 1.5, empty: -1.5, ignore: -2 })[ds.lobby];
            if (p === 3 && ds.lobby === 'ignore') sup.lobbyAftermath = -1;
            if (p === 3) sup.dilemma = ({ quick: 8, hold: 0, pact: -5 })[ds.election];
            let dSup = 0;
            Object.keys(sup).forEach(k => { dSup += sup[k] || 0; });
            ds.support = this._r1(this._clamp(ds.support + dSup, 0, 100));

            // 10 · the ballot box decides what the agency can spend next
            if (p === 3) {
                if (ds.election === 'pact') { ds.pact = true; ds.outcome = 'pact'; ds.budget = 14; ds.pactAlloc = alloc.slice(); }
                else if (ds.support >= 58) { ds.outcome = 'renewed'; ds.budget = 14; }
                else if (ds.support >= 48) { ds.outcome = 'trimmed'; ds.budget = 11; }
                else if (ds.support >= 38) { ds.outcome = 'cut'; ds.budget = 8; }
                else { ds.outcome = 'closed'; ds.budget = 3; ds.agencyAlive = false; }
                const undo = ds.outcome === 'closed' ? 0.5 : (ds.outcome === 'cut' ? 0.25 : 0);
                if (undo > 0) {
                    ds.vint.forEach(v => { v.k = v.k.map((k, i) => (this._maturity(p - v.p, S[i].lag + v.shift) < 1 ? k * (1 - undo) : k)); });
                }
            }
            if (p === 5) ds.finalRec = d.voFinal || 'spread';

            // 11 · aggregates
            const legacyGdp = 58 * ds.legacy / 100;
            ds.gdp = this._r1(legacyGdp + 42 + newOut);
            ds.concentration = this._r1(legacyGdp / (legacyGdp + 42 + newOut) * 100);
            ds.hhi = newOut >= 0.05 ? this._r2(ds.out.reduce((a, o) => a + Math.pow(o / newOut, 2), 0)) : null;
            const risk = this._risk(ds);
            ds.exposure = risk ? this._r1(risk.exposure * 100) : 0;

            return {
                period: p,
                year: this.YEARS[p - 1] || (2026 + p),
                concentration: ds.concentration,
                fund: ds.fund,
                netJobs: netJobs,
                support: Math.round(ds.support),
                supportExact: ds.support,
                alloc: alloc.slice(),
                legacySpend: legacySpend,
                levels: { talent: talent, local: local, housing: housing },
                cumJobs: ds.jobs,
                gdp: ds.gdp,
                hhi: ds.hhi,
                exposure: ds.exposure,
                housing: ds.housing,
                legacy: ds.legacy,
                newOutput: this._r2(newOut),
                sectorsActive: active,
                belowThreshold: this._r1(below),
                fillSpec: Math.round(fillSpec * 100),
                fillGen: Math.round(fillGen * 100),
                created: created,
                displaced: displaced,
                talentIn: talentIn,
                talentCap: ds.talentCap,
                rent: Math.round((ds.housing - 3) * 5),
                budget: ds.budget,
                budgetNext: ds.budget,
                unspent: this._r1(unspent),
                instrument: instrKey,
                outcome: ds.outcome,
                agencyAlive: ds.agencyAlive,
                dSupport: this._r1(ds.support - prevSupport),
                dFund: this._r1(ds.fund - prevFund),
                out: ds.out.slice(),
                stock: ds.stock.slice(),
                legacyGdp: this._r1(legacyGdp),
                drivers: { support: sup, fund: note.fund },
                shock: p === 4 ? ds.shock : null,
                lobby: p === 2 ? ds.lobby : null,
                election: p === 3 ? ds.election : null,
                promise: p === 1 ? ds.promise : null,
                finalRec: p === 5 ? ds.finalRec : null
            };
        }

        // The decisions of a year nobody has played yet: the last plan carried on,
        // cut to whatever budget the ballot box left, and after 2031 reshaped by
        // the recommendation the team signs.
        _carryOn(ds, lastDec, rec, p) {
            const S = this.SECTORS;
            const d = Object.assign({}, lastDec);
            const base = S.map(s => parseFloat(lastDec[s.id]) || 0);
            const tot = base.reduce((a, b) => a + b, 0);
            if (p <= 5) {
                const f = Math.min(1, ds.budget / this.BUDGET);
                S.forEach((s, i) => { d[s.id] = base[i] * f; });
                d.voLegacy = (parseFloat(lastDec.voLegacy) || 0) * f;
                return d;
            }
            const cont = ({ pact: 1, renewed: 0.9, trimmed: 0.7, cut: 0.45, closed: 0 })[ds.outcome || 'renewed'];
            let money = tot * cont;
            let split = base.slice();
            const risk = this._risk(ds);
            if (rec === 'double' && risk) {
                const rest = Math.max(0.01, tot - base[risk.index]);
                split = base.map((b, i) => (i === risk.index ? 0.6 * tot : 0.4 * tot * b / rest));
            } else if (rec === 'spread') {
                const on = S.map((s, i) => (ds.stock[i] >= s.threshold * 0.6 ? 1 : 0));
                const n = on.reduce((a, b) => a + b, 0);
                if (n > 0) split = on.map(o => o * tot / n);
            } else if (rec === 'rebuild') {
                if (p <= 7) money = 0;
                const gaps = S.map((s, i) => ({ i: i, gap: Math.max(0, s.threshold - ds.stock[i]) })).sort((x, y) => x.gap - y.gap);
                split = [0, 0, 0, 0, 0];
                split[gaps[0].i] = tot / 2; split[gaps[1].i] = tot / 2;
            }
            const sTot = split.reduce((a, b) => a + b, 0) || 1;
            S.forEach((s, i) => { d[s.id] = split[i] / sTot * money; });
            d.voLegacy = (parseFloat(lastDec.voLegacy) || 0) * cont;
            if (cont === 0) { d.voTalent = 0; d.voLocal = 0; d.voHousing = 0; }
            ds.budget = this.BUDGET * cont;
            return d;
        }

        // Where the country stands in 2036 if the last plan is carried on.
        _project(dsNow, lastDec, rec, fromP) {
            const ds = JSON.parse(JSON.stringify(dsNow));
            delete ds.snap;
            const path = [];
            for (let p = fromP; p <= 10; p++) {
                const d = this._carryOn(ds, lastDec, rec, p);
                if (p === 8) this._applyShock(ds, { voShock: 'letgo' }, { sup: {}, fund: {} });
                const r = this._step(ds, d, p);
                path.push({ year: 2026 + p, concentration: r.concentration, gdp: r.gdp, hhi: r.hhi });
            }
            return path;
        }

        // The same ten years with no agency at all: the counterfactual.
        _baseline() {
            const ds = this._freshState();
            const d = { voInstrument: 'grant' };
            const path = [];
            for (let p = 1; p <= 10; p++) {
                ds.budget = 0;
                const r = this._step(ds, d, p);
                path.push({ year: 2026 + p, concentration: r.concentration, gdp: r.gdp });
            }
            return path;
        }

        _score(last, proj) {
            if (!last) return { score: 0, parts: {} };
            const c = (v, lo, hi) => this._clamp((v - lo) / (hi - lo), 0, 1);
            const growth = c(last.gdp, 94, 100);
            const end = proj && proj.length ? proj[proj.length - 1] : null;
            const parts = {
                diversification: 25 * c(58 - last.concentration, 0, 6) * growth,
                robustness: (last.newOutput >= 1 && last.hhi !== null) ? 15 * c(0.62 - last.hhi, 0, 0.34) : 0,
                jobs: 12 * c(last.cumJobs, -600, 900),
                fund: 13 * c(last.fund, 8, 13),
                support: 10 * c(last.support, 40, 65),
                legacy: end ? 25 * c(56 - end.concentration, 0, 10) * c(end.gdp, 94, 101) *
                    (1 - 0.5 * c(end.hhi === null ? 1 : end.hhi, 0.4, 0.8)) : 0
            };
            let score = 0;
            Object.keys(parts).forEach(k => { parts[k] = this._r1(parts[k]); score += parts[k]; });
            let cap = 100;
            if (last.agencyAlive === false) cap = Math.min(cap, 35);
            if (last.fund < 6) cap = Math.min(cap, 50);
            if (last.hhi !== null && last.hhi > 0.6) cap = Math.min(cap, 61);
            return { score: Math.round(Math.min(score, cap)), parts: parts, capped: score > cap };
        }
        // ─────────────────────────────────────────────────────────────────
        //  USF CONTRACT
        // ─────────────────────────────────────────────────────────────────

        initialize(state) {
            state.domainState = state.domainState || {};
            if (state.domainState.v !== 2) state.domainState = this._rebuild(state);
            state.decisions = state.decisions || {};
        }

        validateDecisions(decisions) {
            const target = decisions || this._state().decisions || {};
            Object.assign(target, this._readControls());
            const issue = this._problem(target, this._state());
            if (issue) this._warn(this._t(issue.key, issue.vars));
            return !issue;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            this._wire();
            this._bindRepaint();
            this._scheduleRender(true);
        }

        // Round wrapper: idempotent per period, so a re-submitted or previewed
        // round always starts from the same opening position.
        _computeRound(state) {
            const p = this._period(state);
            let ds = state.domainState;
            if (!ds || ds.v !== 2) ds = state.domainState = this._freshState();
            if (ds.snap && ds.snap.p === p) {
                ds = state.domainState = Object.assign(JSON.parse(ds.snap.s), { snap: ds.snap });
            } else {
                const opening = Object.assign({}, ds);
                delete opening.snap;
                ds.snap = { p: p, s: JSON.stringify(opening) };
            }
            const d = this._withDefaults(state.decisions);
            const r = this._step(ds, d, p);
            const rec = p === 5 ? (d.voFinal || 'spread') : 'spread';
            r.proj = p < 10 ? this._project(ds, d, rec, p + 1) : [];
            const sc = this._score(r, r.proj.filter(x => x.year > 2031));
            r.score = sc.score;
            r.scoreParts = sc.parts;
            r.capped = sc.capped;
            r.tier = this._tier(r);
            // The platform grades from domainState.performance.overallScore
            // (express_compute_grade in results_utils.php); results.score alone
            // reaches the progress table but never the gradebook.
            ds.performance = { overallScore: r.score, grade: r.tier === 'closed' ? 'closed' : r.tier.toUpperCase() };
            r.overallScore = r.score;
            return r;
        }

        // A save that reaches us without a v2 model is rebuilt. The exact snapshot the
        // framework keeps in each history record wins; failing that, the decisions the
        // history still holds are replayed (v1 saves included). Records that carry
        // neither are ignored rather than replayed as empty years.
        _rebuild(state) {
            const hist = (Array.isArray(state.history) ? state.history : []).filter(h => h && typeof h === 'object');
            for (let i = hist.length - 1; i >= 0; i--) {
                const snap = hist[i].domainState;
                if (snap && snap.v === 2 && Array.isArray(snap.vint)) return JSON.parse(JSON.stringify(snap));
            }
            const ds = this._freshState();
            let year = 0;
            hist.forEach(rec => {
                const d = rec.decisions || {};
                const mapped = Object.assign({}, d);
                if (Array.isArray(d.alloc)) {
                    this.SECTORS.forEach((s, k) => { mapped[s.id] = d.alloc[k]; });
                    mapped.voLegacy = d.legacy; mapped.voInstrument = d.instrument;
                    mapped.voTalent = d.talent; mapped.voLocal = d.local; mapped.voHousing = d.housing;
                    mapped.voElection = d.election; mapped.voFinal = d.final;
                }
                const usable = mapped.voInstrument !== undefined || this.SECTORS.some(s => mapped[s.id] !== undefined);
                if (usable && year < this.YEARS.length) { year++; this._step(ds, this._withDefaults(mapped), year); }
            });
            return ds;
        }

        _tier(r) {
            if (r.agencyAlive === false) return 'closed';
            return r.score >= 75 ? 'a' : (r.score >= 60 ? 'b' : (r.score >= 45 ? 'c' : 'd'));
        }

        // ─────────────────────────────────────────────────────────────────
        //  HELPERS
        // ─────────────────────────────────────────────────────────────────

        _sim() { return window.mySimulation || null; }
        _state() { const s = this._sim(); return (s && s.state) ? s.state : { currentPeriod: 1, domainState: this._freshState(), decisions: {}, history: [] }; }
        _el(id) { return document.getElementById(id); }
        _set(id, v) { const e = this._el(id); if (e) e.textContent = String(v); }
        _period(state) { return Math.max(1, Math.min(parseInt(state.currentPeriod, 10) || 1, this.YEARS.length)); }
        _history(state) { return (state && Array.isArray(state.history)) ? state.history.filter(h => h && h.results && h.results.year) : []; }
        _last(state) { const h = this._history(state); return h.length ? h[h.length - 1].results : null; }
        _warn(msg) { try { this._sim().uiManager.showNotification(msg, 'warning'); } catch (e) { } }

        _isComplete(state) {
            const s = this._sim();
            try { if (s && typeof s.isRunComplete === 'function') return !!s.isRunComplete(); } catch (e) { }
            return this._history(state).some(h => parseInt(h.period, 10) >= this.YEARS.length);
        }

        // vcI18n is the only live source of the language in production.
        _lang() {
            const norm = (v) => String(v).split('-')[0].toLowerCase();
            try {
                if (window.vcI18n && window.vcI18n._lang) return norm(window.vcI18n._lang);
                const s = this._sim();
                if (s && s.language) return norm(s.language);
                if (s && s.currentLanguage) return norm(s.currentLanguage);
                if (document.documentElement && document.documentElement.lang) return norm(document.documentElement.lang);
            } catch (e) { }
            return 'en';
        }

        _locale() { return ({ ca: 'ca-ES', es: 'es-ES', en: 'en-GB' })[this._lang()] || this._lang(); }

        _t(key, vars) {
            let out = key;
            try { out = this._sim().t(key); } catch (e) { }
            if (vars) Object.keys(vars).forEach(k => { out = String(out).split('{' + k + '}').join(vars[k]); });
            return out;
        }

        _fmt(v, dec) {
            const n = Number(v) || 0, d = dec || 0;
            try { return n.toLocaleString(this._locale(), { minimumFractionDigits: d, maximumFractionDigits: d }); } catch (e) { return n.toFixed(d); }
        }
        _signed(v, dec) { const n = Number(v) || 0; const body = this._fmt(Math.abs(n), dec); return n > 0 ? '+' + body : (n < 0 ? '−' + body : body); }

        _withDefaults(dec) {
            const base = { voInstrument: 'grant', voTalent: 0, voLocal: 0, voHousing: 0, voLegacy: 0 };
            this.SECTORS.forEach(s => { base[s.id] = 0; });
            return Object.assign(base, dec || {});
        }

        _readControls() {
            const d = {};
            const num = (id) => { const e = this._el(id); const v = e ? parseFloat(e.value) : NaN; return isNaN(v) ? 0 : v; };
            const sel = (id, dflt) => { const e = this._el(id); return (e && e.value) ? e.value : dflt; };
            this.SECTORS.forEach(s => { d[s.id] = num(s.id); });
            d.voLegacy = num('voLegacy');
            d.voTalent = num('voTalent'); d.voLocal = num('voLocal'); d.voHousing = num('voHousing');
            d.voInstrument = sel('voInstrument', 'grant');
            d.voPromise = sel('voPromise', 'quiet');
            d.voLobby = sel('voLobby', 'ignore');
            d.voElection = sel('voElection', 'hold');
            d.voShock = sel('voShock', 'letgo');
            d.voFinal = sel('voFinal', 'spread');
            return d;
        }

        // Money already spoken for this year before a single line is chosen.
        _reserved(d, ds, p) {
            let out = (ds.pact && (p === 4 || p === 5)) ? this.PACT_TOLL : 0;
            if (p === 2 && d.voLobby === 'compensate') out += this.COMPENSATION;
            if (p === 4 && d.voShock === 'replace') { const r = this._risk(ds); if (r && r.exposure >= 0.01) out += this.REPLACE; }
            return out;
        }

        _ledger(d, ds, p) {
            let lines = (parseFloat(d.voLegacy) || 0);
            this.SECTORS.forEach(s => { lines += parseFloat(d[s.id]) || 0; });
            const programs = (d.voTalent || 0) * this.COST.voTalent + (d.voLocal || 0) * this.COST.voLocal + (d.voHousing || 0) * this.COST.voHousing;
            const reserved = this._reserved(d, ds, p);
            const used = lines + programs + reserved;
            return { budget: ds.budget, lines: lines, programs: programs, reserved: reserved, used: used, left: ds.budget - used };
        }

        // The band a pact fixes around each 2029 line. If the floors alone would
        // not fit in what is left of the budget, they shrink pro rata, so a team
        // that signed a pact on a one-sector plan is never left without a legal move.
        _pactBounds(ds, p) {
            const ref = ds.pactAlloc || [0, 0, 0, 0, 0];
            const cap = Math.max(0.5, Math.floor(ds.budget * 2) / 2);
            const room = Math.max(0, ds.budget - this.PACT_LEGACY - this.PACT_TOLL - (p === 4 ? this.REPLACE : 0));
            let lo = ref.map(v => Math.max(0, v - this.PACT_BAND));
            const sum = lo.reduce((a, b) => a + b, 0);
            if (sum > room) lo = lo.map(v => Math.floor(v * room / sum * 2) / 2);
            return ref.map((v, i) => ({ lo: lo[i], hi: Math.min(cap, v + this.PACT_BAND) }));
        }

        _problem(d, state) {
            const ds = state.domainState || this._freshState();
            const p = this._period(state);
            const L = this._ledger(d, ds, p);
            if (L.left < -1e-6) return { key: 'warn_budget', vars: { over: this._fmt(-L.left, 1), budget: this._fmt(L.budget, 1) } };
            if (L.left > 2 + 1e-6) return { key: 'warn_budget_low', vars: { left: this._fmt(L.left, 1) } };
            if (ds.pact && p >= 4) {
                if ((d.voLegacy || 0) < this.PACT_LEGACY - 1e-6) return { key: 'warn_pact_legacy', vars: { v: this._fmt(this.PACT_LEGACY, 1) } };
                const lim = this._pactBounds(ds, p);
                const off = this.SECTORS.filter((s, i) => (d[s.id] || 0) < lim[i].lo - 1e-6 || (d[s.id] || 0) > lim[i].hi + 1e-6);
                if (off.length) return { key: 'warn_pact_band', vars: { sector: this._t(off[0].key), v: this._fmt(this.PACT_BAND, 1) } };
            }
            return null;
        }

        // ─────────────────────────────────────────────────────────────────
        //  WIRING AND REPAINT
        // ─────────────────────────────────────────────────────────────────

        _wire() {
            const ids = this.SECTORS.map(s => s.id).concat(['voLegacy', 'voTalent', 'voLocal', 'voHousing',
                'voInstrument', 'voPromise', 'voLobby', 'voElection', 'voShock', 'voFinal']);
            ids.forEach(id => {
                const e = this._el(id);
                if (!e || e._voWired) return;
                e._voWired = true;
                const live = () => { try { this._renderLive(this._state()); } catch (err) { } };
                e.addEventListener('input', live);
                e.addEventListener('change', live);
            });
        }

        // applyTranslations only rewrites data-i18n nodes. Everything this adapter
        // writes itself has to be redrawn when the language, the round or the
        // history changes.
        _bindRepaint() {
            if (this._bound) return;
            this._bound = true;
            const repaint = () => this._scheduleRender(true);
            try { document.addEventListener('express:langchanged', repaint); } catch (e) { }
            try {
                const bus = this._sim() && this._sim().eventBus;
                if (bus && typeof bus.on === 'function') {
                    ['language:changed', 'period:submitted', 'period:undone', 'state:loaded', 'state:imported', 'simulation:reset']
                        .forEach(evt => bus.on(evt, repaint));
                }
            } catch (e) { }
        }

        _scheduleRender(withCharts) {
            setTimeout(() => {
                try {
                    const s = this._sim();
                    if (!s || !s.state) return;
                    this._render(s.state);
                    if (withCharts && typeof s.updateCharts === 'function') s.updateCharts();
                } catch (e) { }
            }, 40);
        }

        _syncControlsFromDecisions(state) {
            const d = state.decisions || {};
            Object.keys(d).forEach(k => {
                const e = this._el(k);
                if (e && ('value' in e) && d[k] !== undefined && d[k] !== null && typeof d[k] !== 'object') e.value = d[k];
            });
        }

        _render(state) {
            const ds = (state.domainState && state.domainState.v === 2) ? state.domainState : this._freshState();
            const done = this._isComplete(state);
            const p = this._period(state);
            const last = this._last(state);
            const hist = this._history(state);
            const prev = hist.length > 1 ? hist[hist.length - 2].results : null;

            this._set('voYear', done ? '2031' : this.YEARS[p - 1]);
            const steps = this._el('voSteps');
            if (steps && steps.children) {
                Array.prototype.forEach.call(steps.children, (li, i) => {
                    li.classList.toggle('vo2064-done', done || i + 1 < p);
                    li.classList.toggle('vo2064-now', !done && i + 1 === p);
                });
            }

            // headline indicators, with the change against the year before
            const delta = (id, now, before, dec, goodUp) => {
                const e = this._el(id);
                if (!e) return;
                if (!last) { e.textContent = ''; return; }
                const dv = now - before;
                e.textContent = Math.abs(dv) < 1e-9 ? '' : this._signed(dv, dec);
                e.className = (dv > 0) === goodUp ? 'vo2064-up' : 'vo2064-down';
            };
            this._set('voConc', this._fmt(ds.concentration, 1) + ' %');
            this._set('voFund', this._fmt(ds.fund, 1));
            this._set('voJobs', ds.jobs === 0 ? '0' : this._signed(ds.jobs, 0));
            this._set('voSupport', this._fmt(ds.support, 1));
            delta('voConcD', ds.concentration, prev ? prev.concentration : 58, 1, false);
            delta('voFundD', ds.fund, prev ? prev.fund : 14, 1, true);
            delta('voJobsD', ds.jobs, prev ? prev.cumJobs : 0, 0, true);
            delta('voSupportD', ds.support, prev ? (prev.supportExact !== undefined ? prev.supportExact : prev.support) : 62, 1, true);

            const hot = (id, on) => { const e = this._el(id); if (e) e.classList.toggle('vo2064-hot', !!on); };
            this._set('voHhi', ds.hhi === null || ds.hhi === undefined ? '—' : this._fmt(ds.hhi, 2));
            hot('voHhi', ds.hhi !== null && ds.hhi > 0.5);
            this._set('voExposure', last && last.newOutput >= 0.3 ? this._fmt(ds.exposure, 0) + ' %' : '—');
            hot('voExposure', ds.exposure >= 20);
            const rent = Math.round((ds.housing - 3) * 5);
            this._set('voRent', this._signed(rent, 0) + ' %');
            hot('voRent', rent >= 20);
            this._set('voFill', last ? (last.fillSpec + ' % · ' + last.fillGen + ' %') : '—');
            hot('voFill', last && (last.fillSpec < 85 || last.fillGen < 85));
            this._set('voLegacyIdx', this._fmt(ds.legacy, 1));
            this._set('voScore', last ? (this._fmt(last.score, 0) + ' / 100') : '—');

            // briefing: a data-i18n-html node, so the framework also retranslates it
            const brief = this._el('voBrief');
            if (brief) {
                const key = done ? 'briefEnd' : ('brief' + p);
                brief.setAttribute('data-i18n-html', key);
                brief.innerHTML = this._t(key);
            }
            this._renderAlerts(state, ds, p, last, done);
            this._renderReport(last);

            // one dilemma per year
            const panels = { voPanelPromise: 1, voPanelLobby: 2, voPanelElection: 3, voPanelShock: 4, voPanelFinal: 5 };
            Object.keys(panels).forEach(id => { const e = this._el(id); if (e) e.classList.toggle('vo2064-on', !done && panels[id] === p); });
            const dec = this._el('voDecisions');
            if (dec) dec.style.display = done ? 'none' : '';
            this._renderFinal(state, last, done);

            if (!done) {
                if (this._syncedFor !== hist.length + ':' + p) {
                    this._syncedFor = hist.length + ':' + p;
                    this._syncControlsFromDecisions(state);
                }
                this._applyBounds(ds, p);
                this._renderLive(state);
            }
            this._labelCharts();
        }

        // Slider limits follow the money the agency really has, the band a pact
        // fixed, and the moratorium a rent backlash can impose on talent permits.
        _applyBounds(ds, p) {
            const bound = (id, lo, hi) => {
                const e = this._el(id);
                if (!e) return;
                e.min = String(lo); e.max = String(hi);
                const v = parseFloat(e.value);
                if (!isNaN(v)) e.value = String(Math.max(lo, Math.min(hi, v)));
            };
            const cap = Math.max(0.5, Math.floor(ds.budget * 2) / 2);
            const pactOn = ds.pact && p >= 4 && Array.isArray(ds.pactAlloc);
            const lim = pactOn ? this._pactBounds(ds, p) : null;
            this.SECTORS.forEach((s, i) => {
                if (pactOn) bound(s.id, lim[i].lo, lim[i].hi);
                else bound(s.id, 0, cap);
            });
            bound('voLegacy', pactOn ? this.PACT_LEGACY : 0, cap);
            bound('voTalent', 0, ds.talentCap === undefined ? 3 : ds.talentCap);
        }

        _previewMass(ds, d, p) {
            const sim = JSON.parse(JSON.stringify(ds));
            delete sim.snap;
            if (p === 4) this._applyShock(sim, d, { sup: {}, fund: {} });
            const keep = (sim.pact ? 0.85 : 1) * (1 - 0.5 * sim.embed);
            const kept = [0, 0, 0, 0, 0];
            sim.vint.forEach(v => v.k.forEach((k, i) => { kept[i] += k * (1 - v.dep * keep); }));
            const I = this.INSTRUMENT[d.voInstrument] || this.INSTRUMENT.grant;
            let f = I.mult;
            if (p === 3 && d.voElection === 'quick') f *= 0.7;
            if (p === 3 && d.voElection !== 'pact') f *= 0.95;
            if (p === 2 && d.voLobby === 'codesign' && (d.voLocal || 0) >= 2) f *= 0.9;
            const added = this.SECTORS.map(s => (parseFloat(d[s.id]) || 0) * f);
            if (p === 4 && d.voShock === 'replace' && sim.shock && sim.shock.sector >= 0 && sim.shock.response !== 'none') added[sim.shock.sector] += this.REPLACE * I.mult;
            return { kept: kept, added: added };
        }

        _renderLive(state) {
            const ds = (state.domainState && state.domainState.v === 2) ? state.domainState : this._freshState();
            const p = this._period(state);
            const d = this._readControls();
            const mass = this._previewMass(ds, d, p);

            this.SECTORS.forEach((s, i) => {
                this._set(s.id + 'Out', this._fmt(d[s.id], 1));
                const total = mass.kept[i] + mass.added[i];
                const info = this._el(s.id + 'Info');
                if (info) {
                    const ok = total >= s.threshold - 1e-9;
                    info.textContent = this._t(ok ? 'thOk' : 'thShort', { t: this._fmt(s.threshold, 1), have: this._fmt(total, 1), gap: this._fmt(Math.max(0, s.threshold - total), 1) });
                    info.classList.toggle('vo2064-ok', ok);
                }
            });
            this._set('voLegacyOut', this._fmt(d.voLegacy, 1));
            const erosion = 3 - 3.4 * (1 - Math.exp(-d.voLegacy / 3.5)) - ((p === 2 && d.voLobby === 'compensate') ? 0.5 : 0);
            this._set('voLegacyInfo', this._t('legacyInfo', { v: this._fmt(Math.max(0, erosion), 1) }));

            const people = Math.round(d.voTalent * 110 * this._clamp(1 - 0.06 * Math.max(0, ds.housing - 4), 0.5, 1));
            this._set('voTalentOut', this._fmt(d.voTalent, 0));
            this._set('voLocalOut', this._fmt(d.voLocal, 0));
            this._set('voHousingOut', this._fmt(d.voHousing, 0));
            this._set('voTalentInfo', this._t('progTalent', { c: this._fmt(d.voTalent * this.COST.voTalent, 1), n: this._fmt(people, 0) }));
            this._set('voLocalInfo', this._t('progLocal', { c: this._fmt(d.voLocal * this.COST.voLocal, 1), n: this._fmt(d.voLocal * 80, 0) }));
            this._set('voHousingInfo', this._t('progHousing', { c: this._fmt(d.voHousing * this.COST.voHousing, 1) }));

            this._renderProfile(d.voInstrument);
            this._renderDilemmaNotes(ds, d, p);

            const L = this._ledger(d, ds, p);
            const box = this._el('voBudget');
            if (box) {
                let txt = this._t('budgetLabel', {
                    year: this.YEARS[p - 1], budget: this._fmt(L.budget, 1), lines: this._fmt(L.lines, 1),
                    programs: this._fmt(L.programs, 1), left: this._fmt(L.left, 1)
                });
                if (L.reserved > 0) txt += ' ' + this._t('budgetReserved', { v: this._fmt(L.reserved, 1) });
                if (L.left > 0.01 && L.left <= 2) txt += ' ' + this._t('budgetUnspent');
                box.textContent = txt;
                box.classList.toggle('vo2064-over', L.left < -1e-6);
            }

            try {
                const ui = this._sim().uiManager;
                if (ui && ui.charts && ui.charts.voChartMass) ui.updateChart('voChartMass', this._massData(mass));
            } catch (e) { }
        }

        _renderProfile(key) {
            const box = this._el('voProfile');
            if (!box) return;
            const I = this.INSTRUMENT[key] || this.INSTRUMENT.grant;
            const rows = [
                ['pfLeverage', I.mult / 1.45, false],
                ['pfSpeed', 1 - (I.shift + 0.5) / 1.5 * 0.75, false],
                ['pfStay', Math.max(0.04, 1 - I.dep / 0.22), false],
                ['pfSupport', (I.support + 1) / 3, false],
                ['pfFund', key === 'fiscal' ? 1 : (key === 'capture' ? 0.5 : 0.02), true],
                ['pfAnchor', Math.max(0.02, (I.anchor + 0.05) / 0.55), true]
            ];
            box.innerHTML = rows.map(r => '<div class="vo2064-bar' + (r[2] ? ' vo2064-cost' : '') + '">' + this._t(r[0]) +
                '<div><span style="width:' + Math.round(this._clamp(r[1], 0, 1) * 100) + '%"></span></div></div>').join('');
        }

        _renderDilemmaNotes(ds, d, p) {
            this._set('voPromiseNote', this._t('note_' + d.voPromise));
            let lobbyKey = 'note_' + d.voLobby;
            if (d.voLobby === 'codesign' && (d.voLocal || 0) < 2) lobbyKey = 'note_codesign_empty';
            this._set('voLobbyNote', this._t(lobbyKey));
            this._set('voElectionNote', this._t('note_' + d.voElection, { s: this._fmt(ds.support, 1) }));
            this._set('voFinalNote', this._t('note_' + d.voFinal));
            if (p === 4) {
                const risk = this._risk(ds);
                const help = this._el('voShockHelp');
                if (help) {
                    help.textContent = (risk && risk.exposure >= 0.01)
                        ? this._t('shockHelp', { sector: this._t(this.SECTORS[risk.index].key), share: this._fmt(risk.share * 100, 0), loss: this._fmt(risk.exposure * 100, 0) })
                        : this._t('shockHelpLow');
                }
                this._set('voShockNote', (risk && risk.exposure >= 0.01) ? this._t('note_' + d.voShock) : '');
            }
        }

        _renderAlerts(state, ds, p, last, done) {
            const box = this._el('voAlerts');
            if (!box) return;
            const items = [];
            const add = (cls, key, vars) => items.push('<div class="vo2064-alert ' + cls + '">' + this._t(key, vars) + '</div>');
            if (ds.outcome && (p >= 4 || done)) {
                add(ds.outcome === 'pact' || ds.outcome === 'renewed' ? 'vo2064-good' : 'vo2064-crit', 'out_' + ds.outcome, { b: this._fmt(ds.budget, 0) });
            }
            if (ds.pact && p >= 4 && !done) add('', 'alert_pact', { v: this._fmt(this.PACT_LEGACY, 1), band: this._fmt(this.PACT_BAND, 1), toll: this._fmt(this.PACT_TOLL, 1) });
            if (ds.shock && ds.shock.sector >= 0 && ds.shock.response !== 'none' && (p === 5 || done)) {
                add('', 'alert_shock', { sector: this._t(this.SECTORS[ds.shock.sector].key), loss: this._fmt(ds.shock.loss * 100, 0), lost: this._fmt(ds.shock.lost, 1) });
            }
            if (ds.shock && ds.shock.response === 'none' && (p === 5 || done)) add('vo2064-good', 'alert_noshock');
            if (last && last.lobby === 'empty' && p === 3) add('', 'alert_empty');
            if (ds.fund < 9) add('vo2064-crit', 'alert_fund', { v: this._fmt(ds.fund, 1) });
            if (ds.talentCap < 3 && !done) add('vo2064-crit', 'alert_talentcap', { r: this._fmt(Math.round((ds.housing - 3) * 5), 0) });
            if (last && last.belowThreshold >= 1 && !done) add('', 'alert_below', { v: this._fmt(last.belowThreshold, 1) });
            if (last && (last.fillSpec < 85 || last.fillGen < 85) && !done) add('', 'alert_labour', { a: last.fillSpec, b: last.fillGen });
            box.innerHTML = items.join('');
        }

        _renderReport(last) {
            const box = this._el('voReport');
            if (!box) return;
            box.classList.toggle('vo2064-on', !!last);
            if (!last) return;
            this._set('voReportLine', this._t('reportLine', {
                year: last.year, conc: this._fmt(last.concentration, 1), net: this._signed(last.netJobs, 0),
                created: this._signed(last.created, 0), displaced: this._fmt(last.displaced, 0),
                dfund: this._signed(last.dFund, 1), dsup: this._signed(last.dSupport, 1), out: this._fmt(last.newOutput, 1)
            }));
        }

        _renderFinal(state, last, done) {
            const box = this._el('voFinalPanel');
            if (!box) return;
            box.classList.toggle('vo2064-on', !!(done && last));
            if (!done || !last) return;
            const sum = this.getPerformanceSummary(state.history);
            this._set('voTier', sum.performanceLabel);
            this._set('voScoreBig', this._t('scoreLine', { v: this._fmt(sum.score, 0) }));
            const max = { diversification: 25, robustness: 15, jobs: 12, fund: 13, support: 10, legacy: 25 };
            const parts = last.scoreParts || {};
            const el = this._el('voParts');
            if (el) {
                el.innerHTML = Object.keys(max).map(k => '<div class="vo2064-bar">' + this._t('part_' + k) +
                    '<div><span style="width:' + Math.round(this._clamp((parts[k] || 0) / max[k], 0, 1) * 100) + '%"></span></div><b>' +
                    this._fmt(parts[k] || 0, 1) + ' / ' + max[k] + '</b></div>').join('');
            }
            const ul = this._el('voInsights');
            if (ul) ul.innerHTML = sum.insights.map(t => '<li>' + t + '</li>').join('');
            const modal = this._el('usf-completion-content') || this._el('completionContent');
            if (modal && modal.innerHTML) modal.innerHTML = this.formatCompletionMessage(sum);
        }

        // ─────────────────────────────────────────────────────────────────
        //  FEEDBACK
        // ─────────────────────────────────────────────────────────────────

        getHint(state, results) {
            this._scheduleRender(true);
            if (!results || !results.year) return null;
            const ds = state.domainState || {};
            if (results.agencyAlive === false && results.period === 3) return this._t('hint_dead');
            if (results.period === 3) return this._t('hint_' + results.election, { o: this._t('outShort_' + results.outcome) });
            if (results.period === 4 && results.shock && results.shock.response !== 'none') return this._t('hint_shock_' + results.shock.response);
            if (results.belowThreshold >= 3) return this._t('hint_wasted', { v: this._fmt(results.belowThreshold, 1) });
            if (results.fund < 9) return this._t('hint_fund');
            if (results.talentCap < 3) return this._t('hint_rent');
            if (results.fillSpec < 85 || results.fillGen < 85) return this._t('hint_labour');
            if (results.rent >= 12 && (state.decisions.voHousing || 0) === 0) return this._t('hint_housing');
            if (results.hhi !== null && results.hhi > 0.55 && results.newOutput >= 1) return this._t('hint_hhi');
            if (results.period === 1) return this._t('hint_p1');
            if (results.period === 2) return this._t('hint_p2');
            if (results.legacy < 92 && results.period >= 3) return this._t('hint_legacy');
            return this._t('hint_generic');
        }

        getPerformanceSummary(history) {
            const hist = (history || []).filter(h => h && h.results && h.results.year);
            const last = hist.length ? hist[hist.length - 1].results : null;
            const tier = last ? (last.tier || this._tier(last)) : 'd';
            const score = last ? (last.score || 0) : 0;
            const insights = [];
            if (last) {
                const end = (last.proj || []).length ? last.proj[last.proj.length - 1] : null;
                insights.push(this._t('ins_conc', { v: this._fmt(last.concentration, 1), g: this._fmt(last.gdp, 1) }));
                if (last.gdp < 97) insights.push(this._t('ins_shrink'));
                insights.push(this._t('ins_jobs', { v: this._signed(last.cumJobs, 0) }));
                insights.push(this._t('ins_fund', { v: this._fmt(last.fund, 1) }));
                this._runInsights(hist.map(h => h.results), last).forEach(t => insights.push(t));
                if (last.hhi !== null && last.hhi > 0.5 && last.newOutput >= 1) insights.push(this._t('ins_hhi', { v: this._fmt(last.hhi, 2) }));
                else if (last.hhi !== null && last.sectorsActive >= 3) insights.push(this._t('ins_spread', { v: this._fmt(last.hhi, 2), n: last.sectorsActive }));
                if (last.agencyAlive === false) insights.push(this._t('ins_closed'));
                else if (last.outcome) insights.push(this._t('ins_' + last.outcome));
                if (end) insights.push(this._t('ins_2036', { v: this._fmt(end.concentration, 1), g: this._fmt(end.gdp, 1) }));
                if (last.finalRec) insights.push(this._t('ins_rec_' + this._recVerdict(last)));
                if (last.capped) insights.push(this._t('ins_capped'));
            }
            if (last) { insights.push(this._t('ins_q_portfolio')); insights.push(this._t('ins_q_second')); }
            insights.push(this._t('ins_transfer'));
            return {
                totalPeriods: hist.length,
                performance: 'tier_' + tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._t('tier_' + tier),
                composite: score, overallScore: score, totalScore: score, score: score,
                insights: insights
            };
        }

        // What this run did, read from its own history: the vote that was lost and why,
        // money that stayed below a threshold, a rent moratorium, a budget spent on
        // the old economy, and posts nobody was trained for. Each line appears only
        // when the run shows it.
        _runInsights(rs, last) {
            const out = [];
            const S = this.SECTORS;
            const full = rs.filter(r => r && Array.isArray(r.alloc) && Array.isArray(r.stock));
            const vote = rs.filter(r => r && r.period === 3)[0];
            if (vote && (vote.outcome === 'trimmed' || vote.outcome === 'cut' || vote.outcome === 'closed')) {
                const sup = {};
                rs.forEach(r => {
                    const m = (r && r.period <= 3 && r.drivers && r.drivers.support) || {};
                    Object.keys(m).forEach(k => { sup[k] = (sup[k] || 0) + (m[k] || 0); });
                });
                let worst = null;
                // fatigue is the same for every team: name what this team could have changed
                Object.keys(sup).forEach(k => { if (k !== 'fatigue' && sup[k] < 0 && (worst === null || sup[k] < sup[worst])) worst = k; });
                if (worst !== null) {
                    let label = this._t(worst === 'jobs' ? 'hJobs' : 'drv_' + worst), cost = sup[worst];
                    if (worst === 'dilemma') {
                        // name the dilemma itself, by the title of its own panel
                        const titles = { 1: 'promTitle', 2: 'lobbyTitle', 3: 'elecTitle' };
                        let at = null;
                        rs.forEach(r => { const v = (r && r.period <= 3 && r.drivers && r.drivers.support && r.drivers.support.dilemma) || 0; if (v < 0 && (at === null || v < at.v)) at = { p: r.period, v: v }; });
                        if (at && titles[at.p]) { label = this._t(titles[at.p]); cost = at.v; }
                    }
                    out.push(this._t('ins_turn_vote', { s: this._fmt(vote.supportExact !== undefined ? vote.supportExact : vote.support, 1), driver: label, d: this._signed(cost, 1) }));
                }
            }
            if (full.length === rs.length && rs.length) {
                let stuck = 0;
                const names = [];
                S.forEach((s, i) => {
                    let peak = 0, put = 0;
                    rs.forEach(r => { peak = Math.max(peak, r.stock[i] || 0); put += r.alloc[i] || 0; });
                    if (peak < s.threshold && put > 0) { stuck += put; names.push(this._t(s.key + 'S')); }
                });
                if (stuck >= 3) out.push(this._t('ins_thin', { v: this._fmt(stuck, 1), sectors: names.join(', ') }));
                let toLegacy = 0, toNew = 0;
                rs.forEach(r => { toLegacy += r.legacySpend || 0; r.alloc.forEach(v => { toNew += v || 0; }); });
                if (toLegacy > toNew) out.push(this._t('ins_defend', { a: this._fmt(toLegacy, 1), b: this._fmt(toNew, 1), c: this._fmt(last.concentration, 1) }));
                const capped = rs.filter(r => r.talentCap < 3)[0];
                if (capped) {
                    let lost = 0;
                    rs.forEach(r => { lost += (r.drivers && r.drivers.support && r.drivers.support.housing) || 0; });
                    out.push(this._t('ins_rent', { r: this._fmt(capped.rent, 0), year: capped.year, d: this._fmt(Math.abs(lost), 1) }));
                }
                let low = null;
                rs.forEach(r => { if (r.fillGen < 85 && (low === null || r.fillGen < low.fillGen)) low = r; });
                if (low) {
                    let trained = 0;
                    rs.forEach(r => { if (r.period < low.period) trained += (r.levels && r.levels.local) || 0; });
                    if (trained === 0) out.push(this._t('ins_untrained', { year: low.year, b: this._fmt(low.fillGen, 0) }));
                }
            }
            return out;
        }

        // Does the recommendation fit the portfolio the team actually built?
        _recVerdict(last) {
            const hhi = last.hhi === null ? 1 : last.hhi;
            if (last.finalRec === 'double') return hhi > 0.4 ? 'double_bad' : 'double_ok';
            if (last.finalRec === 'rebuild') return last.sectorsActive >= 3 ? 'rebuild_bad' : 'rebuild_ok';
            return last.sectorsActive <= 1 ? 'spread_bad' : 'spread_ok';
        }

        formatCompletionMessage(summary) {
            const items = (summary.insights || []).map(t => '<li>' + t + '</li>').join('');
            return '<div class="vo2064-debrief"><h4>' + summary.performanceLabel + '</h4><p><strong>' +
                this._t('scoreLine', { v: this._fmt(summary.score, 0) }) + '</strong> · ' + this._t('debrief_periods') + ': ' + summary.totalPeriods +
                '</p><ul>' + items + '</ul></div>';
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.year',          label: this._t('hYear'),    i18nKey: 'hYear' },
                { key: 'results.concentration', label: this._t('hConc'),    i18nKey: 'hConc',    formatter: v => this._fmt(v, 1) + ' %' },
                { key: 'results.hhi',           label: this._t('hHhi'),     i18nKey: 'hHhi',     formatter: v => this._fmt(v, 2) },
                { key: 'results.netJobs',       label: this._t('hJobs'),    i18nKey: 'hJobs',    formatter: v => this._signed(v, 0) },
                { key: 'results.fund',          label: this._t('hFund'),    i18nKey: 'hFund',    formatter: v => this._fmt(v, 1) },
                { key: 'results.supportExact',  label: this._t('hSupport'), i18nKey: 'hSupport', formatter: v => ((v === undefined || v === null || v === '') ? '—' : this._fmt(v, 1)) },
                { key: 'results.sectorsActive', label: this._t('hActive'),  i18nKey: 'hActive' },
                { key: 'results.score',         label: this._t('hScore'),   i18nKey: 'hScore',   formatter: v => this._fmt(v, 0) }
            ];
        }

        // ─────────────────────────────────────────────────────────────────
        //  CHARTS  (labels travel with the data, so a language switch relabels them)
        // ─────────────────────────────────────────────────────────────────

        getChartConfig() {
            const grid = { color: 'rgba(20,29,43,.08)' };
            const legend = { position: 'bottom', labels: { boxWidth: 12, font: { size: 11 } } };
            const line = (color, extra) => Object.assign({ label: '', data: [], borderColor: color, backgroundColor: color, borderWidth: 2, tension: 0.25, pointRadius: 3, fill: false, spanGaps: true }, extra || {});
            const bar = (color, extra) => Object.assign({ label: '', data: [], backgroundColor: color, borderWidth: 0 }, extra || {});
            const opt = (o) => Object.assign({ animation: false, responsive: true, maintainAspectRatio: false }, o);
            const drivers = () => ({
                type: 'bar',
                data: { labels: [], datasets: [bar('#1d3f57')] },
                options: opt({ indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { grid: grid }, y: { grid: { display: false }, ticks: { font: { size: 11 } } } } })
            });
            return {
                voChartMass: {
                    type: 'bar',
                    data: { labels: [], datasets: [
                        bar('#1d3f57', { stack: 'cap' }),
                        bar('#8fb3c9', { stack: 'cap' }),
                        line('#a33017', { type: 'line', showLine: false, pointStyle: 'line', pointRadius: 17, pointHoverRadius: 17, pointBorderWidth: 3, stack: 'thr' })
                    ] },
                    options: opt({ plugins: { legend: legend }, scales: { x: { stacked: true, grid: { display: false }, ticks: { font: { size: 11 } } }, y: { stacked: true, beginAtZero: true, grid: grid } } })
                },
                voChartSupport: drivers(),
