                    type: 'line',
                    data: { labels: [], datasets: [
                        line('#1d3f57', { borderWidth: 3 }),
                        line('#0f6b5c', { borderDash: [6, 4] }),
                        line('#7b8894', { borderDash: [3, 3], pointRadius: 0 })
                    ] },
