                },
                voChartPortfolio: {
                    type: 'bar',
                    data: { labels: [], datasets: this.SECTORS.map(s => bar(s.color, { stack: 'new', yAxisID: 'y' })).concat([
                        line('#141d2b', { type: 'line', yAxisID: 'y1', borderDash: [5, 4] })
                    ]) },
                    options: opt({ plugins: { legend: legend }, scales: {
                        x: { stacked: true, grid: { display: false } },
                        y: { stacked: true, beginAtZero: true, position: 'left', grid: grid },
                        y1: { position: 'right', suggestedMin: 92, suggestedMax: 104, grid: { drawOnChartArea: false } }
                    } })
                },
                voChart: {
                    type: 'line',
                    data: { labels: [], datasets: [
                        line('#9a4a17', { yAxisID: 'y' }),
                        line('#0f6b5c', { yAxisID: 'y' }),
