                }
            };
        }

        _massData(mass) {
            return {
                labels: this.SECTORS.map(s => this._t(s.key + 'S')),
                datasets: [
                    { label: this._t('cMassHave'), data: mass.kept.map(v => this._r2(v)) },
                    { label: this._t('cMassAdd'), data: mass.added.map(v => this._r2(v)) },
                    { label: this._t('cMassThr'), data: this.SECTORS.map(s => s.threshold) }
                ]
            };
        }

        _driverData(map, prefix) {
            const keys = Object.keys(map || {}).filter(k => Math.abs(map[k] || 0) >= 0.05);
            return {
                labels: keys.map(k => this._t(prefix + k)),
                datasets: [{ label: '', data: keys.map(k => map[k]), backgroundColor: keys.map(k => (map[k] >= 0 ? '#0f6b5c' : '#b4483a')) }]
            };
        }

        getChartData(state) {
            const st = state || {};
            const hist = this._history(st);
            const rs = hist.map(h => h.results);
            const last = rs.length ? rs[rs.length - 1] : null;
            const ds = (st.domainState && st.domainState.v === 2) ? st.domainState : this._freshState();
            const years = rs.map(r => r.year);
            const out = {};

            let mass = { kept: [0, 0, 0, 0, 0], added: [0, 0, 0, 0, 0] };
            try { mass = this._previewMass(ds, this._readControls(), this._period(st)); } catch (e) { }
            out.voChartMass = this._massData(mass);

            const drv = last && last.drivers ? last.drivers : {};
            out.voChartSupport = this._driverData(drv.support, 'drv_');
            out.voChartFund = this._driverData(drv.fund, 'drv_');

            // 2026 to 2036: what was played, what follows if the plan goes on, and no agency at all
            if (!this._basePath) this._basePath = this._baseline();
            const span = [];
            for (let y = 2026; y <= 2036; y++) span.push(y);
            const played = span.map(y => { if (y === 2026) return 58; const r = rs.filter(x => x.year === y)[0]; return r ? r.concentration : null; });
            const proj = (last && Array.isArray(last.proj)) ? last.proj : [];
            const ahead = span.map(y => { if (last && y === last.year) return last.concentration; const q = proj.filter(x => x.year === y)[0]; return q ? q.concentration : null; });
            const none = span.map(y => { if (y === 2026) return 58; const b = this._basePath.filter(x => x.year === y)[0]; return b ? b.concentration : null; });
            out.voChartProj = { labels: span, datasets: [
                { label: this._t('cYou'), data: played },
                { label: this._t('cPlan'), data: ahead },
                { label: this._t('cNoAgency'), data: none }
            ] };

            out.voChartPortfolio = { labels: years, datasets: this.SECTORS.map((s, i) => ({
                label: this._t(s.key + 'S'), data: rs.map(r => (r.out ? r.out[i] : null))
            })).concat([{ label: this._t('cGdp'), data: rs.map(r => (r.gdp === undefined ? null : r.gdp)) }]) };

            out.voChart = { labels: [2026].concat(years), datasets: [
                { label: this._t('cConc'), data: [58].concat(rs.map(r => r.concentration)) },
                { label: this._t('cSupport'), data: [62].concat(rs.map(r => (r.supportExact !== undefined ? r.supportExact : r.support))) },
                { label: this._t('cFund'), data: [14].concat(rs.map(r => r.fund)) }
            ] };

            out.voChartJobs = { labels: years, datasets: [
                { label: this._t('cCreated'), data: rs.map(r => (r.created === undefined ? null : r.created)) },
                { label: this._t('cDisplaced'), data: rs.map(r => (r.displaced === undefined ? null : -r.displaced)) },
                { label: this._t('cCumJobs'), data: rs.map(r => r.cumJobs) }
            ] };
            return out;
        }

